        elif self.arpack_dict['ido'] == 2:
            self.workd[yslice] = self.B(self.workd[xslice])

        elif self.arpack_dict['ido'] == 3:
            raise ValueError("ARPACK requested user shifts. Assure ISHIFT==0")

        elif self.arpack_dict['ido'] == 4:
