def drive(A, k, v0, ncv=20, tol=0, maxiter=None, inplace=True):
    n = A.shape[0]
    if maxiter is None:
        maxiter = n * 200
    data, indices, indptr = A.data, A.indices, A.indptr
    fn = _sparsetools.csr_matvec
    ybuf = np.empty(n, dtype=np.float64)

    def matvec(x):
        if inplace:
            # shouldn't be used
            fn(n, n, indptr, indices, data, x, ybuf)
            return ybuf
        else:
            y = np.empty(n, dtype=np.float64)
            fn(n, n, indptr, indices, data, x, y)
            return y

    params = _UnsymmetricArpackParams(
        n, k, 'd', matvec, mode=1,
        ncv=ncv, v0=v0, maxiter=maxiter, which='LM', tol=tol,
    )
    solver = params._arpack_solver
    ad = params.arpack_dict
    if inplace:
        while True:
            solver(ad, params.resid, params.v, params.ipntr, params.workd, params.workl)
            ido = ad['ido']
            if ido in (1, 5, -1):
                x0 = params.ipntr[0]; y0 = params.ipntr[1]
                fn(n, n, indptr, indices, data, params.workd[x0:x0+n], params.workd[y0:y0+n])
            elif ido == 2:
                x0 = params.ipntr[0]; y0 = params.ipntr[1]
                params.workd[y0:y0+n] = params.workd[x0:x0+n]
            else:
                break
    else:
        while not params.converged:
            params.iterate()
    return params

